#!/system/bin/sh
printf '%s\n' '正在寻找HMA-OSS目录'
a=$(find /data/misc -maxdepth 3 -type d -iname 'hide_my_applist*' 2>/dev/null | head -n 1)
if [ -z "$a" ]; then
  printf '%s\n' '寻找失败：未找到HMA-OSS目录'
  exit 1
fi
printf '%s\n' '寻找成功'
printf '%s\n' '正在配置'
b=$a/config.json
if ! printf '%s' '' | base64 -d > "$b"; then
  printf '%s\n' '配置失败：写入配置文件失败'
  exit 1
fi
if ! chmod 0777 "$b"; then
  printf '%s\n' '配置失败：设置文件权限失败'
  exit 1
fi
printf '%s\n' '配置完毕'
